The approach is a greedy construction followed by a book-assignment pass. I have not compiled or run it against any data set.

**Library ordering.** Libraries are chosen one at a time. At the current time `t`, each candidate library has `rem = D - t - T` days left to scan, so it can ship at most `cap = rem * M` books. Its value is the sum of the top `cap` scores among its books that are not yet taken. The library with the best value divided by `T` (or value divided by `T^1.0`) is picked next.

**Lazy evaluation.** Re-scoring every library at every step would be too slow, so I use a priority queue with lazy re-evaluation. A library's value only decreases as books become taken, and its time-dependent cap also decreases as `t` grows. So a stored score is an upper bound on the true score. I pop the top entry and recompute its score at the current state. If it is still at least the next top entry's stored score, I pick it. Otherwise I push it back with the new score.

**Recomputing a score.** Each library keeps its books sorted by score in descending order. To score it, I scan the list, skip taken books, and sum up to `cap` books. This is O(N) per evaluation, which is acceptable given that the total number of books is at most 10^6 and re-evaluations are lazy. To limit the worst case I stop scanning once `cap` books are collected, and I also drop taken books from the front of the list permanently where I can.

**Picking and output.** When a library is picked, I take its first `min(cap, available)` untaken books in descending score order and mark them taken. Libraries with `rem <= 0` or no available books are discarded. For output, I emit libraries only if they have at least one book, in pick order, and list the books in descending score order. Each library ships `M` books per day in the listed order, so the output stays valid.

**Score metric.** The score is `value / T`. A slightly better variant would use `value / T` with a tie-break, but this form is simple and works well in practice.

**Implementation details.** I use fast input reading. Scores are doubles in the priority queue, and ties are broken by library index so the output is deterministic.

```cpp
#include <bits/stdc++.h>
using namespace std;
int main(){
    int B,L,D;
    scanf("%d %d %d",&B,&L,&D);
    vector<int> S(B);
    for(auto&x:S)scanf("%d",&x);
    vector<int> T(L),M(L);
    vector<vector<int>> bk(L);
    for(int j=0;j<L;j++){
        int n;
        scanf("%d %d %d",&n,&T[j],&M[j]);
        bk[j].resize(n);
        for(auto&x:bk[j])scanf("%d",&x);
        sort(bk[j].begin(),bk[j].end(),[&](int a,int b){
            if(S[a]!=S[b])return S[a]>S[b];
            return a<b;});
    }
    vector<char> taken(B,0);
    vector<int> start(L,0);
    long long t=0;
    auto eval=[&](int j,long long t)->double{
        long long rem=D-t-T[j];
        if(rem<=0)return -1;
        long long cap=rem*(long long)M[j];
        size_t &st=*(new size_t(0));
        delete &st;
        long long cnt=0,sum=0;
        for(size_t i=start[j];i<bk[j].size()&&cnt<cap;i++){
            int b=bk[j][i];
            if(taken[b])continue;
            sum+=S[b];cnt++;
        }
        if(cnt==0)return -1;
        return (double)sum/T[j];
    };
    priority_queue<pair<double,int>> pq;
    for(int j=0;j<L;j++){
        double v=eval(j,0);
        if(v>=0)pq.push({v,-j});
    }
    vector<pair<int,vector<int>>> res;
    while(!pq.empty()){
        auto [v,nj]=pq.top();pq.pop();
        int j=-nj;
        // drop taken books from the front
        while(start[j]<(int)bk[j].size()&&taken[bk[j][start[j]]])start[j]++;
        double nv=eval(j,t);
        if(nv<0)continue;
        if(!pq.empty()&&nv<pq.top().first){
            pq.push({nv,-j});
            continue;
        }
        long long rem=D-t-T[j];
        long long cap=rem*(long long)M[j];
        vector<int> chosen;
        for(size_t i=start[j];i<bk[j].size()&&(long long)chosen.size()<cap;i++){
            int b=bk[j][i];
            if(taken[b])continue;
            taken[b]=1;
            chosen.push_back(b);
        }
        if(chosen.empty())continue;
        res.push_back({j,chosen});
        t+=T[j];
    }
    string out;
    out+=to_string(res.size())+"\n";
    for(auto&r:res){
        out+=to_string(r.first)+" "+to_string(r.second.size())+"\n";
        for(size_t i=0;i<r.second.size();i++){
            if(i)out+=' ';
            out+=to_string(r.second[i]);
        }
        out+="\n";
    }
    fputs(out.c_str(),stdout);
}
```
